/**
 * Concurrency verification runner for Admin Campaign Pause Reason Popup.
 * Tests:
 * 1. Test A: Concurrent duplicate admin pause calls on same campaign with same reason code
 *    (row lock + state check idempotency under parallel transactions).
 * 2. Test B: Concurrent devices competing for popup claim display quotas (5th allowed claim race)
 *    on the notification generated by the new pause RPC.
 *
 * Requirements:
 * - TEST_DATABASE_URL is the ONLY accepted target; never fall back to DATABASE_URL.
 * - Transaction-local JWT claims and roles with robust reset on release to avoid poisoning pooled connections.
 * - Complete cleanup of seeded UUID-scoped users, profiles, campaigns, notifications, popup states, receipts, and audit events.
 *
 * Usage:
 *   $env:TEST_DATABASE_URL="postgresql://postgres:postgres@localhost:5432/postgres"
 *   node supabase/tests/run-admin-pause-reason-concurrency-test.mjs
 */

import crypto from 'node:crypto';
import assert from 'node:assert/strict';

// Strict requirement: ONLY accept TEST_DATABASE_URL, never fallback to DATABASE_URL
const databaseUrl = process.env.TEST_DATABASE_URL;

if (!databaseUrl) {
  console.log('========================================================================');
  console.log('NOTICE: TEST_DATABASE_URL is not set.');
  console.log('Skipping real multi-connection PostgreSQL concurrency test (UNRUN/SKIPPED).');
  console.log('To run this test against a real PostgreSQL/Supabase test instance:');
  console.log('  export TEST_DATABASE_URL="postgresql://postgres:postgres@localhost:5432/postgres"');
  console.log('  node supabase/tests/run-admin-pause-reason-concurrency-test.mjs');
  console.log('========================================================================');
  process.exit(0);
}

const { default: pg } = await import('pg');
const { Pool } = pg;
const pool = new Pool({ connectionString: databaseUrl, max: 12 });

const runId = crypto.randomUUID().replace(/-/g, '').substring(0, 8);
const admin1Id = crypto.randomUUID();
const admin2Id = crypto.randomUUID();
const targetOwnerId = crypto.randomUUID();
const campId = crypto.randomUUID();

console.log(`=== RUNNING MULTI-CONNECTION ADMIN PAUSE CONCURRENCY TEST (Run: ${runId}) ===`);

/**
 * Execute query within a transaction with transaction-local JWT sub and role,
 * ensuring robust rollback and connection reset before returning to the pool.
 */
async function runAsAuthenticated(client, userId, queryFn) {
  try {
    await client.query('begin');
    await client.query(`select set_config('request.jwt.claim.sub', $1, true)`, [userId]);
    await client.query('set local role authenticated');
    const result = await queryFn();
    await client.query('commit');
    return result;
  } catch (err) {
    try {
      await client.query('rollback');
    } catch {}
    throw err;
  } finally {
    try {
      await client.query(`reset role; select set_config('request.jwt.claim.sub', '', false);`);
    } catch {}
  }
}

let createdNotifId = null;

try {
  // 0. Seed test fixtures as administrative connection (service_role / superuser)
  const setupClient = await pool.connect();
  try {
    await setupClient.query(`
      insert into auth.users(id, email) values
        ('${admin1Id}', 'runner-admin1-${runId}@test.local'),
        ('${admin2Id}', 'runner-admin2-${runId}@test.local'),
        ('${targetOwnerId}', 'runner-owner-${runId}@test.local');

      insert into public.profiles(id, email, display_name, role, is_locked) values
        ('${admin1Id}', 'runner-admin1-${runId}@test.local', 'Runner Admin 1', 'admin', false),
        ('${admin2Id}', 'runner-admin2-${runId}@test.local', 'Runner Admin 2', 'admin', false),
        ('${targetOwnerId}', 'runner-owner-${runId}@test.local', 'Runner Owner', 'member', false)
      on conflict (id) do update set role = excluded.role, is_locked = excluded.is_locked;

      insert into public.campaigns (id, owner_id, app_name, package_name, status)
      values ('${campId}', '${targetOwnerId}', 'Concurrency Test App ${runId}', 'com.conc.app', 'open');
    `);
  } finally {
    setupClient.release();
  }

  // -------------------------------------------------------------------------
  // Test A: Race - Two Admins pausing the same app at the exact same time with same reason
  // -------------------------------------------------------------------------
  console.log('Test A: Concurrent duplicate pause requests on same campaign...');
  const pauseClient1 = await pool.connect();
  const pauseClient2 = await pool.connect();

  let res1, res2;
  try {
    const p1 = runAsAuthenticated(pauseClient1, admin1Id, async () => {
      const q = await pauseClient1.query(
        `select public.admin_pause_campaign_with_reason($1, 'missing_google_group') as r`,
        [campId]
      );
      return q.rows[0].r;
    });

    const p2 = runAsAuthenticated(pauseClient2, admin2Id, async () => {
      const q = await pauseClient2.query(
        `select public.admin_pause_campaign_with_reason($1, 'missing_google_group') as r`,
        [campId]
      );
      return q.rows[0].r;
    });

    const pauseResults = await Promise.allSettled([p1, p2]);
    const pauseFailure = pauseResults.find(result => result.status === 'rejected');
    if (pauseFailure) throw pauseFailure.reason;
    [res1, res2] = pauseResults.map(result => result.value);
  } finally {
    pauseClient1.release();
    pauseClient2.release();
  }

  assert.ok(res1.success, 'Pause client 1 should return success');
  assert.ok(res2.success, 'Pause client 2 should return success');

  // Exactly one must have changed=true and notification_id, the other changed=false and notification_id=null
  const changedCount = (res1.changed ? 1 : 0) + (res2.changed ? 1 : 0);
  assert.equal(changedCount, 1, 'Exactly one concurrent pause should perform the state mutation');

  createdNotifId = res1.changed ? res1.notification_id : res2.notification_id;
  assert.ok(createdNotifId, 'Mutating pause call must return created notification_id');

  const checkClient = await pool.connect();
  try {
    const notifCount = (await checkClient.query(
      `select count(*) as c from public.notifications where data->>'campaign_id' = $1`,
      [campId]
    )).rows[0].c;
    assert.equal(Number(notifCount), 1, 'Exactly one notification created despite concurrent pause requests');

    const popupCount = (await checkClient.query(
      `select count(*) as c from public.notification_popup_states s
       join public.notifications n on n.id = s.notification_id
       where n.data->>'campaign_id' = $1`,
      [campId]
    )).rows[0].c;
    assert.equal(Number(popupCount), 1, 'Exactly one popup state registered');
  } finally {
    checkClient.release();
  }
  console.log('PASS: Concurrent pause race handled idempotently.');

  // -------------------------------------------------------------------------
  // Test B: Competing for 5th claim on the notification created by the new pause RPC
  // -------------------------------------------------------------------------
  console.log('Test B: Concurrent race for fifth popup claim on newly created pause notification...');

  // Fast-forward display_count to 4 via administrative connection
  const ffClient = await pool.connect();
  try {
    await ffClient.query(
      `update public.notification_popup_states set display_count = 4 where notification_id = $1`,
      [createdNotifId]
    );
  } finally {
    ffClient.release();
  }

  // Launch 8 concurrent connections claiming simultaneously using role authenticated for target owner
  const concurrentClients = 8;
  const claimPromises = [];

  for (let i = 0; i < concurrentClients; i++) {
    const sessionId = crypto.randomUUID();
    claimPromises.push((async () => {
      const c = await pool.connect();
      try {
        return await runAsAuthenticated(c, targetOwnerId, async () => {
          const q = await c.query(
            `select public.claim_my_notification_popup($1) as r`,
            [sessionId]
          );
          return q.rows[0].r;
        });
      } finally {
        c.release();
      }
    })());
  }

  const settledClaims = await Promise.allSettled(claimPromises);
  const claimFailure = settledClaims.find(result => result.status === 'rejected');
  if (claimFailure) throw claimFailure.reason;
  const claimResults = settledClaims.map(result => result.value);
  const claimedResults = claimResults.filter(r => r.status === 'claimed');
  const noneResults = claimResults.filter(r => r.status === 'none');

  console.log(`Test B results: ${claimedResults.length} claimed, ${noneResults.length} none.`);
  assert.equal(claimedResults.length, 1, 'Exactly one concurrent connection must receive the 5th claim');
  assert.equal(claimedResults[0].display_count, 5, 'Claimed display_count must be 5');
  assert.equal(noneResults.length, concurrentClients - 1, 'All other concurrent connections must receive status none');

  // Verify final DB state as administrative connection
  const verifyClient = await pool.connect();
  try {
    const finalState = (await verifyClient.query(
      `select display_count from public.notification_popup_states where notification_id = $1`,
      [createdNotifId]
    )).rows[0];
    assert.equal(finalState.display_count, 5, 'Final DB display_count must never exceed 5');
    console.log('PASS: Fifth popup claim concurrency passed cleanly without quota violation.');
  } finally {
    verifyClient.release();
  }

  console.log('=== CONCURRENCY SUITE COMPLETED SUCCESSFULLY ===');
} catch (err) {
  console.error('FAIL: Concurrency suite error:', err);
  // Allow finally to finish fixture cleanup and pool shutdown before exiting.
  process.exitCode = 1;
} finally {
  // Reliable cleanup on both success and failure
  try {
    const cleanupClient = await pool.connect();
    try {
      await cleanupClient.query(`
        delete from public.notification_popup_receipts where notification_id in (
          select id from public.notifications where data->>'campaign_id' = '${campId}'
        );
        delete from public.notification_popup_states where notification_id in (
          select id from public.notifications where data->>'campaign_id' = '${campId}'
        );
        delete from public.notifications where data->>'campaign_id' = '${campId}';
        delete from public.admin_action_events where target_id = '${campId}' or actor_id in ('${admin1Id}', '${admin2Id}');
        delete from public.campaigns where id = '${campId}';
        delete from public.profiles where id in ('${admin1Id}', '${admin2Id}', '${targetOwnerId}');
        delete from auth.users where id in ('${admin1Id}', '${admin2Id}', '${targetOwnerId}');
      `);
    } finally {
      cleanupClient.release();
    }
  } catch (cleanErr) {
    console.error('Warning during fixture cleanup:', cleanErr.message);
    process.exitCode = 1;
  }
  await pool.end();
}
